 let live=true,opened=false,recoveryOnly=false,busy=false,refreshing=null,submitting=false,resultWindowOpened=false,renderedActiveKey=null,syncInterrupted=false,readBlocked=false,identity=null,quote=null,item=null,message='',error='',consent=false,timer=null,revision=0,authLoading=false,authState='unknown';
